{
  "$schema": "https://cmux.dev/schemas/cmux-app/2.json",
  "manifestVersion": 2,
  "id": "local/customize",
  "name": "Codex settings",
  "version": "1.0.0",
  "engines": {
    "cmux": "^2.0"
  },
  "runtime": {
    "main": "main.js"
  },
  "implements": {
    "cmux.session.info.section/1": {
      "export": "renderSettings",
      "title": "Settings",
      "symbol": "gearshape",
      "options": {
        "maxRows": 5
      }
    }
  },
  "scopes": {
    "actions:run": "Open the selected preferences page."
  },
  "description": "Open native appearance, chat font, and keyboard preferences for this setup."
}

files.customize/main.js:
function renderSettings() {
  const open = (action, args = {}) => cmux.actions.run(action, args).catch(error => cmux.toast({ title: "Settings", message: String(error), tone: "warning" }))
  return VStack({ spacing: 4 }, [
    Button("Settings…", () => open("openSettings")),
    Button("Appearance", () => open("openSettings", { setting: "appearance.themeFile" })),
    Button("Chat font", () => open("openSettings", { setting: "agentPane.display.font.size" })),
    Button("Keyboard shortcuts", () => open("keybindings.open"))
  ])
}

globalThis.__cmuxAppExports = { renderSettings }
